package com.nth.desktop3d;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.SystemClock;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.concurrent.atomic.AtomicReference;

/** Data-loss regression: real JSON/file bytes, simulated reinstall, invalid-input rejection and UI restore. */
public final class Backup077Smoke {
    private final Instrumentation test;private final MainActivity activity;private final String output;
    public Backup077Smoke(Instrumentation test,MainActivity activity,String output){this.test=test;this.activity=activity;this.output=output;}
    public void run()throws Exception {
        String prefix="backup077_"+SystemClock.uptimeMillis()+"_";File directory=new File(activity.getCacheDir(),prefix);directory.mkdirs();
        Context isolated=new ContextWrapper(activity){@Override public SharedPreferences getSharedPreferences(String name,int mode){return super.getSharedPreferences(prefix+name,mode);}@Override public File getFilesDir(){return directory;}};
        try{main(()->{try{
            LauncherStore original=new LauncherStore(isolated);CrystalPreferences crystal=new CrystalPreferences(isolated);SettingsModel model=new SettingsModel(original,crystal,rebuild->{});
            for(java.util.List<LauncherStore.Item> page:original.pages)page.clear();LauncherStore.Item folder=new LauncherStore.Item("folder","My saved folder ☺");folder.cellX=1;folder.cellY=2;
            for(int i=0;i<700;i++)folder.children.add(new LauncherStore.Item("builtin:notes","Saved app "+i+" — full folder label"));original.pages.get(1).add(folder);original.page=1;original.setHomePage(2);original.preferences.edit().putString("desktop_name_1","My apps").putBoolean("folder_pattern_page_1",true).putString("note","Keep this note after reinstall").apply();model.set("scene",6);model.set("grid_columns",5);
            byte[] photo=photo();WallpaperStore.write(isolated,photo);model.set("wallpaper_source",1);original.save();
            JSONObject widget=new JSONObject().put("token","saved-widget").put("id",-1).put("page",2).put("provider","com.nth.desktop3d.widgetfixture/.FixtureWidgetProvider").put("user",0).put("label","Saved fixture widget").put("cell_x",1).put("cell_y",2).put("span_x",2).put("span_y",2).put("padding",true);original.preferences.edit().putString("restore_widgets",new JSONArray().put(widget).toString()).apply();
            JSONObject archive=DesktopBackup.capture(isolated,model);check(archive.toString().getBytes("UTF-8").length>65536,"Fixture does not cover the old file-size limit");String expected=archive.getJSONArray("pages").toString();String oldInstall=DesktopBackup.install(isolated);
            // Simulate uninstall/reinstall: user preferences and the private wallpaper are gone.
            isolated.getSharedPreferences("desktop3d",0).edit().clear().commit();isolated.getSharedPreferences("desktop3d_crystal",0).edit().clear().commit();WallpaperStore.write(isolated,null);
            LauncherStore fresh=new LauncherStore(isolated);SettingsModel restored=new SettingsModel(fresh,new CrystalPreferences(isolated),rebuild->{});check(!oldInstall.equals(DesktopBackup.install(isolated)),"Install identity was carried across the simulated reinstall");archive.getJSONObject("settings").getJSONObject("values").put("cloud_ai",1);
            restored.importDesktopBackup(isolated,new DesktopBackup.Prepared(archive,restored));
            check(expected.equals(DesktopBackup.capture(isolated,restored).getJSONArray("pages").toString()),"Folder identities, order, labels or positions were lost");check(fresh.folders().get(0).children.size()==700&&fresh.homePage()==2&&fresh.page==1,"Folders or Home/current desktop were not restored");check("Keep this note after reinstall".equals(fresh.preferences.getString("note","")),"Note was lost");check(java.util.Arrays.equals(photo,WallpaperStore.bytes(isolated))&&restored.value("wallpaper_source")==1,"Photo wallpaper was not self-contained");check(!fresh.preferences.getBoolean("cloud_ai",false),"Backup restored cloud consent");check(new JSONArray(fresh.preferences.getString("restore_widgets","[]")).length()==1,"Widget reapproval placement was lost");check(!fresh.emptyPage(2),"Pending widget placement was treated as an empty removable desktop");
            String before=fresh.preferences.getString("layout","");JSONObject invalid=new JSONObject(archive.toString());JSONArray children=invalid.getJSONArray("pages").getJSONObject(1).getJSONArray("items").getJSONObject(0).getJSONArray("children");children.getJSONObject(1).put("id",children.getJSONObject(0).getString("id"));boolean rejected=false;try{new DesktopBackup.Prepared(invalid,restored);}catch(Exception expectedError){rejected=true;}check(rejected&&before.equals(fresh.preferences.getString("layout","")),"Invalid duplicate IDs changed the desktop");
            invalid=new JSONObject(archive.toString());invalid.getJSONObject("wallpaper").put("sha256","wrong");rejected=false;try{new DesktopBackup.Prepared(invalid,restored);}catch(Exception expectedError){rejected=true;}check(rejected&&before.equals(fresh.preferences.getString("layout","")),"Corrupt photo backup changed the desktop");
            restored.undo();check(!"My saved folder ☺".equals(fresh.folders().get(0).label)&&WallpaperStore.bytes(isolated)==null,"Undo did not restore the pre-import desktop and photo state");
            restored.importDesktopBackup(isolated,new DesktopBackup.Prepared(archive,restored));fresh.movePage(2,0);check(new JSONArray(fresh.preferences.getString("restore_widgets","[]")).getJSONObject(0).getInt("page")==0,"Pending widgets did not follow desktop reordering");
        }catch(Exception e){throw new AssertionError(e);}});}finally{isolated.getSharedPreferences("desktop3d",0).edit().clear().commit();isolated.getSharedPreferences("desktop3d_crystal",0).edit().clear().commit();WallpaperStore.write(isolated,null);directory.delete();}
        SettingsModel model=(SettingsModel)invokeValue("settingsModel");JSONObject original=DesktopBackup.capture(activity,model);File image=new File(activity.getExternalFilesDir(null),"wallpaper-smoke.png");try(FileOutputStream out=new FileOutputStream(image)){out.write(photo());}
        try{
            invoke("wallpaperPhotoResult",new Class[]{int.class,Intent.class},Activity.RESULT_OK,new Intent().setData(Uri.fromFile(image)));await(()->model.value("wallpaper_source")==1&&field("settingsStudio")!=null,"Photo selection did not finish");
            main(()->check(((View)field("scene")).getVisibility()==View.GONE&&((ImageView)field("wallpaper")).getDrawable()!=null,"Photo did not replace the GL wallpaper"));capture("wallpaper-photo-settings");
            main(()->model.set("wallpaper_source",2));check((activity.getWindow().getAttributes().flags&android.view.WindowManager.LayoutParams.FLAG_SHOW_WALLPAPER)!=0,"Android wallpaper was not enabled");capture("android-wallpaper-settings");main(()->model.set("wallpaper_source",1));
            File backup=new File(activity.getExternalFilesDir(null),"desktop-smoke.nth3dbackup");invoke("settingsDocumentResult",new Class[]{int.class,int.class,Intent.class},3071,Activity.RESULT_OK,new Intent().setData(Uri.fromFile(backup)));await(()->backup.isFile()&&backup.length()>300,"Desktop export was not written");idle(500);JSONObject saved;try(InputStream in=new FileInputStream(backup)){saved=new JSONObject(new String(WallpaperStore.read(in,DesktopBackup.MAX_BYTES),"UTF-8"));}check(DesktopBackup.FORMAT.equals(saved.getString("format")),"UI exported the old settings-only format");
            main(()->{LauncherStore store=model.store;store.pages.get(0).clear();store.save();});String empty=model.store.preferences.getString("layout","");invoke("settingsDocumentResult",new Class[]{int.class,int.class,Intent.class},3072,Activity.RESULT_OK,new Intent().setData(Uri.fromFile(backup)));await(()->field("restoreConfirmation")!=null,"Restore preview missing");capture("desktop-backup-preview");main(()->((AlertDialog)field("restoreConfirmation")).getButton(AlertDialog.BUTTON_NEGATIVE).performClick());check(empty.equals(model.store.preferences.getString("layout","")),"Cancel changed desktop contents");
            invoke("settingsDocumentResult",new Class[]{int.class,int.class,Intent.class},3072,Activity.RESULT_OK,new Intent().setData(Uri.fromFile(backup)));await(()->field("restoreConfirmation")!=null,"Restore preview missing on second open");main(()->((AlertDialog)field("restoreConfirmation")).getButton(AlertDialog.BUTTON_POSITIVE).performClick());check(!model.store.folders().isEmpty(),"Native restore did not bring folders back");capture("desktop-backup-restored");
            File legacy=new File(activity.getExternalFilesDir(null),"old-settings.nth3dsettings");try(FileOutputStream out=new FileOutputStream(legacy)){out.write(model.exportSettings().toString().getBytes("UTF-8"));}invoke("settingsDocumentResult",new Class[]{int.class,int.class,Intent.class},3072,Activity.RESULT_OK,new Intent().setData(Uri.fromFile(legacy)));await(()->field("restoreConfirmation")!=null,"Legacy preview missing");capture("settings-only-restore-warning");main(()->((AlertDialog)field("restoreConfirmation")).getButton(AlertDialog.BUTTON_NEGATIVE).performClick());
        }finally{main(()->{try{model.importDesktopBackup(activity,new DesktopBackup.Prepared(original,model));}catch(Exception e){throw new AssertionError(e);}});invoke("closePanel",new Class[]{});image.delete();}
    }
    private static byte[] photo(){Bitmap b=Bitmap.createBitmap(48,72,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(0xFF164C69);Paint p=new Paint();p.setColor(0xFF80D6DF);c.drawCircle(30,20,15,p);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return out.toByteArray();}
    private Object field(String name){try{java.lang.reflect.Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}catch(Exception e){throw new AssertionError(e);}}
    private Object invokeValue(String name){AtomicReference<Object> r=new AtomicReference<>();main(()->{try{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);r.set(m.invoke(activity));}catch(Exception e){throw new AssertionError(e);}});return r.get();}
    private void invoke(String name,Class<?>[] types,Object... args){main(()->{try{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(activity,args);}catch(Exception e){throw new AssertionError(e);}});idle(300);}
    private void main(Runnable r){AtomicReference<Throwable> error=new AtomicReference<>();test.runOnMainSync(()->{try{r.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    private void idle(long ms){SystemClock.sleep(ms);test.runOnMainSync(()->{});}
    private void await(java.util.function.BooleanSupplier ready,String message){long until=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<until){AtomicReference<Boolean> r=new AtomicReference<>(false);main(()->r.set(ready.getAsBoolean()));if(r.get())return;idle(100);}throw new AssertionError(message);}
    private void capture(String name){idle(600);Bitmap b=test.getUiAutomation().takeScreenshot();File dir=output==null?new File(test.getTargetContext().getExternalFilesDir(null),"verification"):new File(output);dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new AssertionError(e);}finally{b.recycle();}}
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
}
